// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.CascadesPlan;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.PhysicalProperties;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A statement pattern without a context term matches a triple once per context that holds it (RDF4J's default graph
 * without a dataset is the union of all contexts). A pattern whose subject, predicate and object are all bound is
 * therefore not limited to one row per invocation when the store holds named graphs, and the cost model must not clamp
 * its estimate to one row per invocation.
 */
class LmdbFullyBoundLookupNamedGraphTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:ex:fully-bound-graphs:";
	private static final IRI A = VF.createIRI(NS, "a");
	private static final IRI P = VF.createIRI(NS, "p");
	private static final IRI B = VF.createIRI(NS, "b");
	private static final IRI Q = VF.createIRI(NS, "q");
	private static final int GRAPHS = 500;
	private static final int OTHER_ROWS = 2_000;

	@Test
	void contextlessFullyBoundPatternKeepsItsPerGraphMultiplicity(@TempDir File dataDir) {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				for (int graph = 0; graph < GRAPHS; graph++) {
					connection.add(A, P, B, VF.createIRI(NS, "g" + graph));
				}
				for (int row = 0; row < OTHER_ROWS; row++) {
					connection.add(VF.createIRI(NS, "s" + row), Q, VF.createIRI(NS, "o" + row));
				}
				connection.commit();
			}

			StatementPattern fullyBound = new StatementPattern(Var.of("_a", A), Var.of("_p", P), Var.of("_b", B));
			StatementPattern other = new StatementPattern(Var.of("s"), Var.of("_q", Q), Var.of("o"));
			TupleExpr input = new Join(fullyBound, other);
			EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
			CascadesPlan plan = new LmdbCascadesOptimizer(statistics, false)
					.planPreparedInput(input, OptimizationGoal.root(input, PhysicalProperties.ANY));

			StatementPattern planned = find(plan.tupleExpr(), P);
			assertNotNull(planned, "expected the planned :a :p :b pattern. plan=" + plan.tupleExpr());
			double invocations = Math.max(1.0d, planned.getDoubleMetricPlanned("plannedRepeatedInvocations"));
			double rowsPerInvocation = planned.getResultSizeEstimate() / invocations;
			assertTrue(rowsPerInvocation >= GRAPHS / 2.0d,
					"the triple is stored in " + GRAPHS + " graphs and a context-less pattern returns one solution "
							+ "per graph, but the plan prices " + rowsPerInvocation + " rows per invocation. rows="
							+ planned.getResultSizeEstimate() + ", doubles=" + planned.getDoubleMetricsPlanned());
		} finally {
			repository.shutDown();
		}
	}

	private static StatementPattern find(TupleExpr optimized, IRI predicate) {
		List<StatementPattern> matches = new ArrayList<>(1);
		optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				if (matches.isEmpty() && node.getPredicateVar() != null
						&& predicate.equals(node.getPredicateVar().getValue())) {
					matches.add(node);
				}
				super.meet(node);
			}
		});
		return matches.isEmpty() ? null : matches.getFirst();
	}
}
